#!/usr/bin/perl
use strict;
use warnings;

my $data = do { local $/; open my $fh, '<:raw', '/app/data.txt' or die $!; <$fh> };
my $N = length $data;
die "NUL byte in data" if index($data, "\0") >= 0;

# ---------- arithmetic encoder (exact inverse of decomp.c) ----------
my @cc;             # adaptive model counts, cc[ctx*2 + bit]
my ($f, $r, $k) = (0, 1, 0);
my $K = 5000;       # generous upper bound on total input bytes
my @P;              # P[i] = 255**i
{
  my $p = 1;
  for my $i (0..$K) { $P[$i] = $p; $p = $p * 255; }
}
my ($L, $H) = (0, $P[$K]);
my @digits;

sub enc_bit {
  my ($b, $ctx) = @_;
  if ($r < 255) {
    my $up  = $P[$K - $k - 1];
    my $dlo = int($L / $up);
    my $dhi = int(($H - 1) / $up);
    $dhi = 254 if $dhi > 254;
    my $c0 = $cc[$ctx*2]    || 0;
    my $c1 = $cc[$ctx*2+1]  || 0;
    my $s_after = int(255 * $r * ($c0+1) / ($c0+$c1+3));
    my $d = -1;
    if ($b) {
      for my $x ($dlo..$dhi) { $d = $x; last if $x >= $s_after - 255*$f; }
    } else {
      for my $x (reverse $dlo..$dhi) { $d = $x; last if $x <= $s_after - 255*$f - 1; }
    }
    die "no valid digit (f=$f r=$r ctx=$ctx b=$b dlo=$dlo dhi=$dhi)" if $d < 0;
    push @digits, $d;
    $L -= $d * $up;
    my $cap = ($d + 1) * $up; $H = $cap if $H > $cap;
    $H -= $d * $up;
    $f = 255 * $f + $d;
    $r = 255 * $r;
    $k++;
  }
  my $c0 = $cc[$ctx*2]   || 0;
  my $c1 = $cc[$ctx*2+1] || 0;
  my $s = int($r * ($c0+1) / ($c0+$c1+3));
  my $bdec = ($f >= $s) ? 1 : 0;
  die "bit mismatch ctx=$ctx b=$b bdec=$bdec f=$f s=$s" if $bdec != $b;
  $f -= $s if $b;
  $r  = $b ? $r - $s : $s;
  $cc[$ctx*2 + $b]++;
}

# Elias-style integer coder, exact inverse of get_integer(tmp, ctx)
sub enc_int {
  my ($v, $t0, $c0) = @_;
  my $c = $c0 * 99;
  my ($start, $size, $n) = (0, 1 << $t0, 1);
  while ($v >= $start + $size) { $n++; $start += $size; $size <<= 1; }
  my $p = $v - $start;
  my $m = $t0 + $n - 1;
  for my $i (0 .. $n-2) { enc_bit(0, $c + $t0 + 1 + $i); }
  enc_bit(1, $c + $t0 + $n);
  for my $i ($m-1 .. 0) { enc_bit(($p >> $i) & 1, $c); }
}

# ---------- LZ77 factorization ----------
my @out;   # [0,lit] or [1,off,len]
my $THRESH = 3;
my %chain; # 4-byte prefix -> arrayref of positions (older first)
my $pos = 0;
while ($pos < $N) {
  my $best_len = 0; my $best_off = 0;
  if ($pos + 4 <= $N) {
    my $key = substr($data, $pos, 4);
    if (my $cl = $chain{$key}) {
      my $cnt = 0;
      for my $q (reverse @$cl) {
        last if $cnt++ >= 64;
        my $off = $pos - $q;
        next if $off < 1 || $off > $pos;
        my $Lm = 0;
        my $max = $N - $pos; $max = 64 if $max > 64;
        while ($Lm < $max && substr($data, $q+$Lm, 1) eq substr($data, $pos+$Lm, 1)) { $Lm++; }
        if ($Lm > $best_len) { $best_len = $Lm; $best_off = $off; }
      }
    }
  }
  if ($best_len >= $THRESH) {
    push @out, [1, $best_off, $best_len];
    for my $i (0 .. $best_len-1) {
      my $s = $pos + $i + 4 <= $N ? substr($data, $pos+$i, 4) : undef;
      push @{$chain{$s}}, $pos + $i if defined $s;
    }
    $pos += $best_len;
  } else {
    push @out, [0, ord(substr($data, $pos, 1))];
    if ($pos + 4 <= $N) { push @{$chain{substr($data, $pos, 4)}}, $pos; }
    $pos++;
  }
}

# ---------- encode ----------
enc_int($N, 9, 0);
for my $sym (@out) {
  if ($sym->[0]) {
    enc_bit(1, 1);
    enc_int($sym->[1] - 1, 5, 2);
    enc_int($sym->[2] - 1, 2, 3);
  } else {
    enc_bit(0, 1);
    enc_bit(0, 8);
    enc_int($sym->[1], 4, 9);
  }
}

my $out = join('', map { chr($_ + 1) } @digits);
open my $oh, '>:raw', '/app/data.comp' or die $!;
print $oh $out;
close $oh;
printf "bytes=%d matches=%d literals=%d\n",
  length($out), scalar(grep { $_->[0] } @out), scalar(grep { !$_->[0] } @out);

